script:
const fs=require("node:fs"),cp=require("node:child_process"),crypto=require("node:crypto");
const dir="docs/coordinator/worktree-completion/evidence/", prefix="dcc1-parity-observer-proof-";
const sha=(b,a="sha256")=>crypto.createHash(a).update(b).digest("hex");
const blob=b=>sha(Buffer.concat([Buffer.from("blob "+b.length+"\0"),b]),"sha1");
const git=(...a)=>cp.execFileSync("git",a,{encoding:"utf8"});
const read=p=>JSON.parse(fs.readFileSync(dir+p,"utf8")), failures=[];
const verify=(ok,label)=>{if(!ok)failures.push(label);};
const pre=read(prefix+"preflight.json"), before=read("dcc1-ae007-postflight.json");
const paths=[...before.bundle.inputs,...before.bundle.outputs,before.bundle.stampFile,...before.parityArtifacts,...before.coverageArtifacts,...before.evidence,...before.archives.flatMap(x=>[{path:x.path,bytes:x.originalBytes,sha256:x.originalSha256},{path:x.archivePath,bytes:x.archiveBytes,sha256:x.archiveSha256}]),...pre.untrackedPins,pre.parent];
for(const x of paths){const b=fs.readFileSync(x.path);verify(b.length===x.bytes&&sha(b)===x.sha256,"retained "+x.path);}
for(const x of pre.proposed)verify(!fs.existsSync(x.path),"protected "+x.path);
const tree=git("write-tree").trim(),head=git("rev-parse","HEAD").trim(),merge=git("rev-parse","MERGE_HEAD").trim();
verify(tree===pre.tree&&head===pre.head&&merge===pre.merge,"git parents/index");
const entries=git("ls-files","-s").trimEnd().split("\n").filter(l=>!l.includes("\tdocs/coordinator/worktree-completion/")).map(l=>{const[m,path]=l.split("\t"),[mode,expected,stage]=m.split(" "); const b=mode==="120000"?Buffer.from(fs.readlinkSync(path)):fs.readFileSync(path); verify(blob(b)===expected&&stage==="0","working "+path); return {path,mode,bytes:b.length,sha256:sha(b),blob:expected,indexBlob:expected};});
const indexed=new Map(entries.map(e=>[e.path,e]));
const patches=[read("dcc1-parity-observer-patch.json"),read(prefix+"supplemental-patch.json")];
const variants=new Map();variants.set(patches[0].instrumentedBlob,patches[0].instrumented);for(const f of patches[1].files)variants.set(f.blob,f.text);
const mutations=fs.readdirSync(dir).filter(f=>f.startsWith(prefix)&&f.endsWith("-mutation.json")).sort().map(f=>({file:f,...read(f)}));
for(const m of mutations){const b=Buffer.from(m.source);verify(blob(b)===m.blob,"mutant blob "+m.property);verify(cp.execFileSync("git",["cat-file","blob",m.blob]).equals(b),"retained Git mutant "+m.property);variants.set(m.blob,m.source);}
const stream=git("ls-tree","-r","--full-tree",tree).split("\n").filter(l=>l&&!/\tdocs\/coordinator\/worktree-completion\/(reports|evidence|handoffs)\//.test(l));
verify(sha(stream.join("\n")+"\n")===pre.closure,"restored closure");
const receipts=[];
for(const f of fs.readdirSync(dir).filter(f=>f.startsWith(prefix)&&f.endsWith(".meta.jsonl")).sort()){
const rows=fs.readFileSync(dir+f,"utf8").trim().split("\n").map(JSON.parse),s=rows[0],t=rows.at(-1),spawn=rows.find(x=>x.event==="spawn");verify(s.event==="start"&&t.event==="terminal"&&spawn!==undefined,"events "+f);
verify(s.head===head&&s.merge===merge&&s.index===tree&&t.index===tree,"gate git "+f);
verify(s.inputs.length===entries.length,"input size "+f);const seen=new Set();
for(const r of s.inputs){seen.add(r.path);const e=indexed.get(r.path);verify(e!==undefined,"unknown input "+r.path);if(!e)continue;const replacement=t.inputs[r.path];const b=replacement===undefined?null:Buffer.from(variants.get(replacement)??"");const expected=b===null?e:{...e,blob:blob(b),bytes:b.length,sha256:sha(b)};
verify(["path","mode","bytes","sha256","blob","indexBlob"].every(k=>r[k]===expected[k]),"input pin "+f+" "+r.path);}
verify(seen.size===entries.length,"unique map "+f);
const by=new Map(s.inputs.map(r=>[r.path,r.blob]));const closure=sha(stream.map(l=>{const [m,p]=l.split("\t");return m.replace(/[0-9a-f]{40}$/,by.get(p))+"\t"+p;}).join("\n")+"\n");
verify(closure===s.executionClosure&&closure===t.executionClosure&&sha(s.closureStream)===closure,"closure "+f);
const rawFile=f.replace(".meta.jsonl",".raw.log"),raw=fs.readFileSync(dir+rawFile);verify(raw.length===t.rawBytes&&sha(raw)===t.rawSha256,"raw "+f);
verify(t.loggerExit===0&&t.signal===null&&t.errors.length===0,"logger "+f);
const red=f.endsWith("-red.meta.jsonl");verify(t.gateExit===(red?1:0),"gate "+f);
if(red){const m=mutations.find(m=>f===prefix+m.property+"-red.meta.jsonl");verify(!!m&&raw.toString().includes(m.expectedRed)&&/1 failed \| 14 skipped/.test(raw.toString()),"meaningful red "+f);}
receipts.push({file:f,command:s.command,start:s.start,end:t.end,gateExit:t.gateExit,loggerExit:t.loggerExit,elapsedSeconds:t.elapsedSeconds,rawFile,rawBytes:t.rawBytes,rawSha256:t.rawSha256,executionClosure:closure,inputs:t.inputs,summary:raw.toString().split("\n").filter(l=>/Test Files|Tests  |Duration|AssertionError/.test(l))});
}
verify(receipts.length===23,"23 worker+parent receipts");
const mutationPairs=mutations.map(m=>{const red=receipts.find(r=>r.file===prefix+m.property+"-red.meta.jsonl"),green=receipts.find(r=>r.file===prefix+m.property+"-restored.meta.jsonl");verify(red&&green&&red.inputs["tests/parity/helpers/capture.ts"]===m.blob&&green.inputs["tests/parity/helpers/capture.ts"]===patches[0].instrumentedBlob&&red.end<=green.start,"ordered pair "+m.property);return {property:m.property,blob:m.blob,expectedRed:m.expectedRed,pinTool:m.pinTool,red:red?.file,restored:green?.file};});
const checks=[["diff","--check"],["diff","--cached","--check"]].map(args=>{const r=cp.spawnSync("git",args,{encoding:"utf8"});verify(r.status===0,"diff check "+args.join(" "));return {args,exit:r.status,output:r.stdout+r.stderr};});
verify(git("diff","--name-only").trim()==="docs/coordinator/worktree-completion/reports/dcc1.md","only parent report delta");verify(git("ls-files","-u")==="","no unmerged");
console.log(JSON.stringify({classification:"Independent parent read-only verification returned through tool transport; not a raw gate log",at:new Date().toISOString(),head,merge,index:tree,restoredClosure:pre.closure,nonCoordinationTracked:entries.length,retainedChecks:paths.length,protectedAbsent:pre.proposed.length,mutations:mutationPairs,receipts,checks,failures,pass:failures.length===0},null,2));process.exitCode=failures.length?1:0;
